
INSERT INTO course_videos (course_id, title, unit, video_url, order_index, description, transcript, exam_tips) VALUES
('a1594f02-e453-4a4d-9129-2ba075474769', 'Ch 1 p1: Introduction to Limits & Motion', 'Unit 1: Limits and Continuity', 'https://www.youtube.com/watch?v=6OOvQQVCISY', 0, 'Introduction to calculus foundations including free fall motion, average vs. instantaneous velocity, and the graphical definition of limits.', '[{"s": 0, "t": "hi welcome to OTI Institute and I''m your"}, {"s": 5, "t": "instructor for AP Calculus AB Brandon So um"}, {"s": 10, "t": "the first thing we are going to talk about"}, {"s": 15, "t": "in AP calculus uh AB the foundation of"}, {"s": 20, "t": "everything is in it''s basically limits and the"}, {"s": 25, "t": "foundation of limits is introduction to limits right"}, {"s": 30, "t": "the first ever chapter that''s ever introduced in calculus"}]', E'• Free Fall Connection: For objects in rest under gravity, $h(t)=\\frac{1}{2}gt^2$ where $g \\approx 9.81 m/s^2$.\n\n• Limit Existence: A limit exists if and only if: $\\lim_{x \\to c^+} f(x) = \\lim_{x \\to c^-} f(x) = L$.'),

('a1594f02-e453-4a4d-9129-2ba075474769', 'Ch 1 p2: Limit Properties & Existence', 'Unit 1: Limits and Continuity', 'https://www.youtube.com/watch?v=LzCjz4w_k_c', 1, 'Discussion on cases where limits do not exist (oscillation, unboundedness, jumps), and techniques for solving limits like substitution and conjugation.', '[{"s": 0, "t": "cases where the limit does not exist right"}, {"s": 5, "t": "here so so the first thing is that"}, {"s": 10, "t": "the right hand limit is not equal to"}, {"s": 15, "t": "the left hand like as I I just"}, {"s": 20, "t": "explained right here and then the second one"}, {"s": 25, "t": "is that um as x approaches c f(x)"}, {"s": 30, "t": "increases or decreases without a bond so it"}]', E'• When Limits DNE: 1. Jump (Left $\\neq$ Right), 2. Unbounded ($\\pm\\infty$), 3. Oscillation.\n\n• Conjugate Method: Multiply by conjugate for limits with square roots, e.g., $\\frac{\\sqrt{x}-1}{x-1}$.'),

('a1594f02-e453-4a4d-9129-2ba075474769', 'Unit 3 Differentiation Part 1: Inverse Functions', 'Unit 3: Composite, Implicit, and Inverse Functions', 'https://www.youtube.com/watch?v=h2R_VGk476A', 2, 'Deriving and applying the formula for the derivative of an inverse function using the chain rule.', '[{"s": 0, "t": "uh this question is testing our knowledge on"}, {"s": 5, "t": "the derivative of an inverse function so an"}, {"s": 10, "t": "inverse function is a function like this you"}, {"s": 15, "t": "basically switch the x and y''s so if"}, {"s": 20, "t": "you want to take the derivative of this"}, {"s": 25, "t": "function we can uh actually derive the formula"}, {"s": 30, "t": "by ourselves so d f inverse x over dx"}]', E'• Inverse Formula: If $g(x)=f^{-1}(x)$, then $g''(x) = \\frac{1}{f''(f^{-1}(x))}$.\n\n• Quick Tip: Point $(a,b)$ on $f \\to (b,a)$ on $f^{-1}$. The derivative at $x=b$ is $1/f''(a)$.'),

('a1594f02-e453-4a4d-9129-2ba075474769', 'Unit 3 Differentiation Part 2: Chain Rule & Product Rule', 'Unit 3: Composite, Implicit, and Inverse Functions', 'https://www.youtube.com/watch?v=g9zBXMqGzSc', 3, 'Application of the Chain Rule and Product Rule to find derivatives of composite functions like sin(1/x).', '[{"s": 0, "t": "for these two question we are asked to"}, {"s": 5, "t": "find the derivative of uh the y So"}, {"s": 10, "t": "for the first question we need to apply"}, {"s": 15, "t": "the chain rule in the section of derivative"}, {"s": 20, "t": "which is um for example y equal to"}, {"s": 25, "t": "f gx This is uh a function inside"}, {"s": 30, "t": "another function And if we want to take"}]', E'• Chain Rule: $\\frac{d}{dx}[f(g(x))] = f''(g(x)) \\cdot g''(x)$. "Outer derivative, inside stays same, times inner derivative."\n\n• Product Rule: $\\frac{d}{dx}[uv] = u''v + uv''$.'),

('a1594f02-e453-4a4d-9129-2ba075474769', 'Unit 3 Differentiation Part 3 & 5: Implicit & Inverse Trig', 'Unit 3: Composite, Implicit, and Inverse Functions', 'https://youtu.be/dE3s8JWwoAc', 4, 'Solving derivatives for implicit functions and inverse trigonometric functions like arcsin(x).', '[{"s": 0, "t": "this question involves the derivative of a uh"}, {"s": 5, "t": "implicit function because there is a y value"}, {"s": 10, "t": "that cannot be separated into a equation like"}, {"s": 15, "t": "this so how are we going to derive"}, {"s": 20, "t": "such equation the method is uh as we"}, {"s": 25, "t": "we derive the equation as usual so first"}, {"s": 30, "t": "we take the derivative of sin x which is"}]', E'• Implicit Differentiation: Differentiating $y$ terms requires multiplying by $\\frac{dy}{dx}$ (Chain Rule).\n\n• Inverse Trig: $\\frac{d}{dx}(\\sin^{-1} x) = \\frac{1}{\\sqrt{1-x^2}}$.'),

('a1594f02-e453-4a4d-9129-2ba075474769', 'Unit 4 Applications Part 1: Related Rates', 'Unit 4: Contextual Applications of Differentiation', 'https://youtu.be/Z6dmg0xMzV8', 5, 'Solving Related Rates problems involving volume of cones and spheres, differentiating with respect to time t.', '[{"s": 0, "t": "this question is uh is called the related"}, {"s": 5, "t": "rate and it''s a type of question that"}, {"s": 10, "t": "will definitely occur on the test So here"}, {"s": 15, "t": "we need to figure out the rate of"}, {"s": 20, "t": "change of the volume with respect to time"}, {"s": 25, "t": "and we know that the rate of change"}, {"s": 30, "t": "is actually the derivative of the function So"}]', E'• Strategy: 1. Write the main formula ($V=\\frac{1}{3}\\pi r^2h$); 2. Differentiate w.r.t $t$; 3. Plug in values.'),

('a1594f02-e453-4a4d-9129-2ba075474769', 'Unit 4 Applications Part 2: Particle Motion', 'Unit 4: Contextual Applications of Differentiation', 'https://youtu.be/sU8-qpNBMDE', 6, 'Analyzing particle motion graphs (position, velocity, acceleration) to determine speeding up or slowing down.', '[{"s": 0, "t": "this question is another one involving the application"}, {"s": 5, "t": "of derivatives and it also involves uh the"}, {"s": 10, "t": "understanding of graph so a particle moves along"}, {"s": 15, "t": "the x-axis and the graph of the particles"}, {"s": 20, "t": "position xt at time t is shown in"}, {"s": 25, "t": "the figure so this line is basically the"}, {"s": 30, "t": "position of the particle and it says the"}]', E'• Speeding Up: Velocity $v(t)$ and Acceleration $a(t)$ have the same sign.\n\n• Slowing Down: $v(t)$ and $a(t)$ have opposite signs.'),

('a1594f02-e453-4a4d-9129-2ba075474769', 'Unit 5 & Ch 6: Derivative Rules & L''Hopital''s Rule', 'Unit 5: Analytical Applications of Differentiation', 'https://youtu.be/swlQt8mj0tU', 7, 'Review of derivative rules and L''Hopital''s Rule for indeterminate limits like 0/0.', '[{"s": 0, "t": "guys welcome back to O2 and today we''re"}, {"s": 5, "t": "going to talk about chapter 5 derivative rules"}, {"s": 10, "t": "okay so the first rule here is the"}, {"s": 15, "t": "constant multiple rule and we talked about this"}, {"s": 20, "t": "in the chapter 4 here we talked about"}, {"s": 25, "t": "it in chapter 4 but yeah so we''re"}, {"s": 30, "t": "going to skip this we also talked about"}]', E'• L''Hopital''s Rule: Apply only for $\\frac{0}{0}$ or $\\frac{\\infty}{\\infty}$. $\\lim \\frac{f(x)}{g(x)} = \\lim \\frac{f''(x)}{g''(x)}$.\n\n• Important: Must show that both numerator and denominator approach $0$ separately.'),

('a1594f02-e453-4a4d-9129-2ba075474769', 'Ch 6 p2: Extrema, Concavity & Linear Approximation', 'Unit 5: Analytical Applications of Differentiation', 'https://youtu.be/OjD2iYs209U', 8, 'Using 1st and 2nd derivative tests to find local extrema and applying linear approximation.', '[{"s": 0, "t": "we are going to continue our lessons So"}, {"s": 5, "t": "move on to 6.4 uh monoponicity concav concavity"}, {"s": 10, "t": "and uh extremma Okay So uh increasing or"}, {"s": 15, "t": "decreasing function So if here if f prime"}, {"s": 20, "t": "of x is greater than zero then f"}, {"s": 25, "t": "is always increasing So these are often tested"}, {"s": 30, "t": "in free response just to let you know"}]', E'• 2nd Derivative Test: $f''(c)=0, f''''(c)<0 \\to$ Local Max; $f''(c)=0, f''''(c)>0 \\to$ Local Min.\n\n• Linear Approximation: $L(x) = f(a) + f''(a)(x-a)$ to estimate values near $a$.');
